      kind: SOURCE_LIVE,
      service: String(x.service || ''),
      format: '',
      count: (typeof x.count === 'number') ? x.count : 0,
      textLen: (typeof x.textLen === 'number') ? x.textLen : 0,
      importedAt: 0
